import React, {FC, useState} from 'react';
import './SearchForm.scss';
import reset from './reset.svg';
import search from './search.svg';

interface SearchFormProps {
    setSearchOptions: (searchOptions: { search: string, sort: string, period: string, priority: string, subject: string }) => void;
}

const SearchForm: FC<SearchFormProps> = (props) => {
    const [searchInput, setSearchInput] = useState<string>('');
    return (
        <form id="search-form" className={'search-form'} onSubmit={(e) => {props.setSearchOptions({})}}>
            <label className={"search-bar"}>
                <label className={"search-input"}>
                    <input type="text" placeholder="Type something..." name="search" id="search-input" value={searchInput}/>
                    <button type="reset" id="reset-button"><img src={reset} alt="reset"/></button>
                </label>
                <span className={"vertical-line"}></span>
                <button type="submit" id="search-button"><img src={search} alt="search"/></button>
            </label>
        </form>
    );
};

export default SearchForm;
